import subprocess
def run(args, input_data=None):
    p = subprocess.run(["./executable"]+args, input=input_data, capture_output=True, text=True)
    return p

def test(flags, pat, inp):
    p = run(["-f", flags, pat, "X"], input_data=inp)
    return p.stdout

# test w + m/e/s for multiline
inp = "foo\nbar\n"
for flags in ["w", "mw", "wm", "m", "ew", "we", "sw", "ws", "msw", "smw", "wms", "esm", "mesw", ""]:
    for pat in ["^bar", "bar$", "foo$", "^foo"]:
        out = test(flags, pat, inp)
        print(f"flags={repr(flags):6} pat={repr(pat):6} -> {repr(out)}")
    print("---")

# test bar$ with e (multiline off) to see if $ matches before final newline
print("=== e vs w for $ at end ===")
for flags in ["", "e", "w", "mw", "m"]:
    for pat in ["bar$", "bar\\n$", "bar\\n", "foo$", "^bar"]:
        out = test(flags, pat, "foo\nbar")
        print(f"flags={repr(flags):4} pat={repr(pat):10} inp='foo\\nbar' -> {repr(out)}")
    for pat in ["bar$", "foo$"]:
        out = test(flags, pat, "foo\nbar\n")
        print(f"flags={repr(flags):4} pat={repr(pat):10} inp='foo\\nbar\\n' -> {repr(out)}")
    print("---")

# test explicit inline flags to bypass outer multiline
print("=== inline flags ===")
for flags in ["", "w", "mw", "e"]:
    for pat in [r"(?m:^bar)", r"(?-m:^bar)", r"(?m:foo$)", r"(?-m:foo$)"]:
        out = test(flags, pat, inp)
        print(f"flags={repr(flags):4} pat={repr(pat):15} -> {repr(out)}")
    print("---")

PY"}

