import subprocess, itertools
def run(args, input_data=None):
    p = subprocess.run(["./executable"]+args, input=input_data, capture_output=True, text=True)
    return p
def test_dot(flags):
    p = run(["-f", flags, "foo.bar", "X"], input_data="foo\nbar\n")
    return p.stdout == 'X\n'
def test_case(flags):
    p = run(["-f", flags, "a", "b"], input_data="A\n")
    return p.stdout == 'b\n'  # True if insensitive
def test_word(flags):
    # word wrapping test: pattern foo should NOT match foobar if word on
    p = run(["-f", flags, "foo", "X"], input_data="foobar\n")
    return p.stdout == 'foobar\n'  # True if word on (no replacement)
def test_ml(flags):
    # need to handle w wrapping transparency: use plain ^bar, but for w cases wrapping transparent as argued
    p = run(["-f", flags, "^bar", "X"], input_data="foo\nbar\n")
    # For w cases, if multiline were on, would it match? We assume wrapping transparent, so match indicates on
    # But we need to verify wrapping transparency for all w cases: use inline (?m:^bar) as control
    # For now just return plain
    return p.stdout == 'foo\nX\n'

# test dot sequential hypothesis: last among s/w determines, default false, s=>True, w=>False
print("=== dot sequential test ===")
mismatch=0
for l in [0,1,2,3,4]:
    for combo in itertools.product(['s','w','m','e','i','c','x'], repeat=l):
        flags=''.join(combo)
        actual = test_dot(flags)
        # predicted: find last among s,w
        last=None
        for ch in flags:
            if ch=='s': last='s'
            elif ch=='w': last='w'
        if last is None:
            pred=False
        elif last=='s':
            pred=True
        else:
            pred=False
        if actual!=pred:
            print(f"DOT MISMATCH flags={repr(flags)} actual={actual} pred={pred}")
            mismatch+=1
            if mismatch>20:
                break
    if mismatch>20:
        break
print(f"dot mismatches={mismatch}")

print("=== case sequential test ===")
mismatch=0
for l in [0,1,2,3,4]:
    for combo in itertools.product(['c','i','w','m','e','s','x'], repeat=l):
        flags=''.join(combo)
        actual = test_case(flags)
        last=None
        for ch in flags:
            if ch=='c': last='c'
            elif ch=='i': last='i'
            elif ch=='w': last='c'  # w acts as c
        if last is None:
            pred=False
        elif last=='i':
            pred=True
        else:
            pred=False
        if actual!=pred:
            print(f"CASE MISMATCH flags={repr(flags)} actual={actual} pred={pred}")
            mismatch+=1
            if mismatch>20:
                break
    if mismatch>20:
        break
print(f"case mismatches={mismatch}")

print("=== word test ===")
for flags in ["", "w", "ww", "sw", "ws", "m", "e", "s", "x", "c", "i"]:
    print(f"flags={repr(flags)} word_on={test_word(flags)}")

print("=== ml contains test ===")
def pred_ml(flags):
    if 'e' in flags or 'w' in flags:
        return False
    elif 'm' in flags:
        return True
    elif 's' in flags:
        return False
    else:
        return True
mismatch=0
for l in [0,1,2,3]:
    for combo in itertools.product(['m','e','s','w','c','i','x'], repeat=l):
        flags=''.join(combo)
        actual = test_ml(flags)
        pred = pred_ml(flags)
        if actual!=pred:
            print(f"ML MISMATCH flags={repr(flags)} actual={actual} pred={pred}")
            mismatch+=1
            if mismatch>20:
                break
    if mismatch>20:
        break
print(f"ml mismatches={mismatch}")
PY"}

