use regex::Regex;
fn main() {
    // test $1a expansion
    let re = Regex::new("(a)").unwrap();
    let hay = "a";
    // test replace with $1a
    // In regex 1.12.4, $1a should be group "1a" => empty, no error
    let result = re.replace(hay, "$1a");
    println!("replace $1a: {:?}", result);
    let result2 = re.replace(hay, "${1}a");
    println!("replace ${{1}}a: {:?}", result2);
    // test invalid regex
    match Regex::new("[") {
        Ok(_) => println!("unexpected ok"),
        Err(e) => println!("invalid regex [: {:?}", e.to_string()),
    }
    // test lookaround
    match Regex::new("(?=a)a") {
        Ok(_) => println!("unexpected ok"),
        Err(e) => println!("lookaround err: {:?}", e.to_string()),
    }
    // test backref
    match Regex::new("(a)\\1") {
        Ok(_) => println!("unexpected ok"),
        Err(e) => println!("backref err: {:?}", e.to_string()),
    }
    // test expand directly
    let caps = re.captures(hay).unwrap();
    let mut dst = String::new();
    caps.expand("$1a", &mut dst);
    println!("expand $1a: {:?}", dst);
}
EOF
