                Ok(_) => {},
                Err(e) => {
                    if e.kind() == io::ErrorKind::BrokenPipe {
                        std::process::exit(0);
                    } else {
                        eprintln!("error: {}", e);
                        std::process::exit(1);
                    }
                }
            }
            match io::stdout().flush() {
                Ok(_) => {},
                Err(e) => {
                    if e.kind() == io::ErrorKind::BrokenPipe {
                        std::process::exit(0);
                    } else {
                        eprintln!("error: {}", e);
                        std::process::exit(1);
                    }
                }
            }
        } else {
