            let mut failures: Vec<(PathBuf, String, String)> = Vec::new(); // (original path, io error display, temp path display)
            for (idx, p) in files.iter().enumerate() {
                let new_content = apply_replacement(&re, &contents[idx], &replacement_intermediate, fixed_strings, max_replacements);
                // Resolve real path for temp dir and rename target (canonicalize)
