                        // Simplify: use parent display + "/.tmpXXXXXX" dummy
                        let dummy_temp = format!("{}/.tmp{}", parent.to_string_lossy(), random_suffix());
                        failures.push((p.clone(), e.to_string(), dummy_temp));
                        continue;
                    }
                };
                let parent = real_path.parent().unwrap_or(Path::new("/")).to_path_buf();
                // Generate temp path: parent + "/.tmp" + 6 random alnum
                let temp_name = format!(".tmp{}", random_suffix());
                let temp_path = parent.join(&temp_name);
                let temp_display = temp_path.to_string_lossy().to_string();
                // Try to create temp file, write, chmod, rename
                // Use File::create (truncate if exists)
                let write_result: io::Result<()> = (|| {
                    // Create
                    let mut f = std::fs::File::create(&temp_path)?;
                    // Write
                    f.write_all(&new_content)?;
                    // Flush? Ensure data written
                    f.flush()?;
                    // Chmod to original mode (from metadatas[idx].permissions())
                    let perms = metadatas[idx].permissions();
                    std::fs::set_permissions(&temp_path, perms)?;
                    drop(f);
                    // Rename onto real_path
                    std::fs::rename(&temp_path, &real_path)?;
                    Ok(())
                })();
                match write_result {
                    Ok(_) => {},
                    Err(e) => {
                        // Clean up temp if exists (ignore errors)
                        let _ = std::fs::remove_file(&temp_path);
                        failures.push((p.clone(), e.to_string(), temp_display));
                        continue;
                    }
                }
            }
            if !failures.is_empty() {
                eprintln!("error: Failed processing some inputs");
                for (orig, err_display, temp_display) in failures {
                    eprintln!("    {}: {} at path \"{}\"", orig.to_string_lossy(), err_display, temp_display);
                }
                eprintln!();
                std::process::exit(1);
            }
        }
    }
}

fn parse_flags(flags: &str) -> (bool, bool, bool, bool) {
    // returns (case_insensitive, multi_line, dot_matches, is_word)
    // case_insensitive, dot_matches are sequential (w acts as false)
    // is_word is contains w
    // multi_line is contains-based with priority
    let mut case_insensitive = false;
    let mut dot_matches = false;
    for c in flags.chars() {
        match c {
            'c' => case_insensitive = false,
            'i' => case_insensitive = true,
            'w' => {
                case_insensitive = false;
                dot_matches = false;
            }
            's' => {
                dot_matches = true;
            }
            _ => {}
        }
    }
    // Note: 'm'/'e' don't affect case/dot, only multiline via contains rule
    // But need to handle 's'/'w' sequential correctly when interleaved with other chars? Already done (only s/w matter for dot, c/i/w for case)
    // For dot, need to consider last among s/w only (other chars ignored) - our loop does that (only s/w change dot)
    // For case, last among c/i/w - our loop does that
    let is_word = flags.contains('w');
    let multi_line = if flags.contains('e') || flags.contains('w') {
        false
    } else if flags.contains('m') {
        true
    } else if flags.contains('s') {
        false
    } else {
        true
    };
    (case_insensitive, multi_line, dot_matches, is_word)
}

