fn unescape_replacement(raw: &str) -> String {
    // Two-pass unescaping with Bug 1 (skip after valid \x/\u)
    // Iterate over chars with index handling for \x/\u (which are ASCII, so byte indices safe? But need to handle multi-byte trailing skip per char)
    // Simplest: collect chars into Vec<char>, iterate with index over chars (not bytes), handling \x/\u by looking ahead chars (which should be ASCII hex? Hex digits are ASCII, so char == byte for those. Good.)
    let chars: Vec<char> = raw.chars().collect();
    let len = chars.len();
    let mut out = String::new();
    let mut i = 0;
    while i < len {
        if chars[i] != '\\' {
            out.push(chars[i]);
            i += 1;
            continue;
        }
        // Found '\\' at i
        if i + 1 >= len {
            // Trailing '\' at end, literal
            out.push('\\');
            i += 1;
            continue;
        }
        let nxt = chars[i+1];
        match nxt {
            'n' => { out.push('\n'); i += 2; },
            't' => { out.push('\t'); i += 2; },
            'r' => { out.push('\r'); i += 2; },
            '\\' => { out.push('\\'); i += 2; },
            '\'' => { out.push('\''); i += 2; },
            '"' => { out.push('"'); i += 2; },
            'x' => {
                // Need 2 hex after x (i+2, i+3)
                if i + 3 < len && chars[i+2].is_ascii_hexdigit() && chars[i+3].is_ascii_hexdigit() {
                    // Valid \xHH
                    let hex_str: String = vec![chars[i+2], chars[i+3]].into_iter().collect();
                    let val = u8::from_str_radix(&hex_str, 16).unwrap(); // 0-255, always valid
                    // Convert to char via from_u32 (0-255 always valid, including 0x00? char::from_u32(0) is Some('\0'), valid. Good.
                    let ch = char::from_u32(val as u32).unwrap();
                    out.push(ch);
                    i += 4; // past \xHH
                    // Bug 1: skip next single char (if any)
                    if i < len {
                        i += 1; // skip (discard)
                    }
                } else {
                    // Invalid, literal '\', advance 1 (leave 'x' for next)
                    out.push('\\');
                    i += 1;
                }
            },
            'u' => {
                // Need 4 hex after u (i+2..i+5)
                if i + 5 < len && chars[i+2].is_ascii_hexdigit() && chars[i+3].is_ascii_hexdigit() && chars[i+4].is_ascii_hexdigit() && chars[i+5].is_ascii_hexdigit() {
                    let hex_str: String = vec![chars[i+2], chars[i+3], chars[i+4], chars[i+5]].into_iter().collect();
                    let val = u32::from_str_radix(&hex_str, 16).unwrap(); // 0-FFFF
                    match char::from_u32(val) {
                        Some(ch) => {
                            out.push(ch);
                            i += 6; // past \uHHHH
                            // Bug 1: skip next
                            if i < len {
                                i += 1;
                            }
                        },
                        None => {
                            // Surrogate (D800-DFFF), invalid, literal '\', advance 1
                            out.push('\\');
                            i += 1;
                        }
                    }
                } else {
                    // Invalid, literal
                    out.push('\\');
                    i += 1;
                }
            },
            _ => {
                // Invalid escape (including 'U', 'a', 'b', 'f', 'v', 'c', 'd', 's', 'w', '/', '0', etc.): literal '\', advance 1
                out.push('\\');
                i += 1;
            }
        }
    }
    out
}

fn apply_replacement(re: &regex::bytes::Regex, input: &[u8], replacement: &[u8], fixed: bool, limit: usize) -> Vec<u8> {
    if fixed {
        if limit == 0 {
            re.replace_all(input, regex::bytes::NoExpand(replacement)).into_owned()
        } else {
            re.replacen(input, limit, regex::bytes::NoExpand(replacement)).into_owned()
        }
    } else {
        if limit == 0 {
            re.replace_all(input, &replacement[..]).into_owned()
        } else {
            re.replacen(input, limit, &replacement[..]).into_owned()
        }
    }
}

fn random_suffix() -> String {
    // Generate 6 random alphanumeric (A-Za-z0-9) using fastrand? Use std + time + pid for seed? Simpler: use tempfile's fastrand? Actually fastrand crate is available via tempfile dependency? But we can just use std::collections::hash_map::RandomState? Or use /dev/urandom?
    // Simplest: read 6 bytes from /dev/urandom (or use getrandom? No, use std::fs::read /dev/urandom? On Linux, /dev/urandom always exists. Good.
    // Fallback to time+pid based pseudo-random if /dev/urandom fails.
    const ALPHANUM: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    let mut bytes = [0u8; 6];
    // Try /dev/urandom
    if let Ok(mut f) = std::fs::File::open("/dev/urandom") {
        use std::io::Read;
        if f.read_exact(&mut bytes).is_ok() {
            let mut s = String::with_capacity(6);
            for b in bytes {
                s.push(ALPHANUM[(b as usize) % 62] as char);
            }
            return s;
        }
    }
    // Fallback: use time + pid + counter
    use std::time::{SystemTime, UNIX_EPOCH};
    let now = SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.as_nanos()).unwrap_or(0);
    let pid = std::process::id() as u128;
    // Simple LCG? Use fastrand-like? Just use hash of now+pid+counter
    static COUNTER: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
    let cnt = COUNTER.fetch_add(1, std::sync::atomic::Ordering::Relaxed) as u128;
    let mut seed = now ^ (pid << 32) ^ (cnt << 64);
    // LCG parameters from Numerical Recipes?
    let mut s = String::with_capacity(6);
    for _ in 0..6 {
        seed = seed.wrapping_mul(6364136223846793005).wrapping_add(1);
        let idx = ((seed >> 33) % 62) as usize;
        s.push(ALPHANUM[idx] as char);
    }
    s
}
