                let is_long = rendered.contains("unexpected argument '--");
                if is_long && !rendered.contains("[OPTIONS]") {
                    if let Some(pos) = rendered.find("Usage: ") {
                        let after = &rendered[pos + "Usage: ".len()..];
                        if let Some(end) = after.find(|c: char| c == ' ' || c == '\n') {
                            let bin = &after[..end];
                            let complex = format!("Usage: {} <--preview|--fixed-strings|--max-replacements <LIMIT>|--flags <FLAGS>|FIND|REPLACE_WITH|FILES>", bin);
                            let usage_start = pos;
                            let usage_end_rel = rendered[usage_start..].find('\n').map(|i| usage_start + i).unwrap_or(rendered.len());
                            let mut new_rendered = String::new();
                            new_rendered.push_str(&rendered[..usage_start]);
                            new_rendered.push_str(&complex);
                            new_rendered.push_str(&rendered[usage_end_rel..]);
                            eprint!("{}", new_rendered);
                            std::process::exit(2);
                        }
                    }
                }
            }
            e.exit()
        }
    };

    let find: &String = matches.get_one("FIND").unwrap();
    let replace_with: &String = matches.get_one("REPLACE_WITH").unwrap();
    let files: Vec<PathBuf> = matches.get_many::<PathBuf>("FILES").map(|v| v.cloned().collect()).unwrap_or_default();
    let preview: bool = matches.get_flag("preview");
    let fixed_strings: bool = matches.get_flag("fixed-strings");
    let max_replacements: usize = *matches.get_one::<usize>("max-replacements").unwrap();
    let flags_str: &str = matches.get_one::<String>("flags").map(|s| s.as_str()).unwrap_or("");

    // Validate replacement for ambiguous (if not fixed)
    if !fixed_strings {
        if let Err(msg) = validate_replacement(replace_with) {
            eprint!("{}", msg);
            std::process::exit(1);
        }
    }

    // Parse flags
    let (case_insensitive, multi_line, dot_matches, is_word) = parse_flags(flags_str);

    // Build pattern
    let pattern_str: String = if fixed_strings {
        let escaped = regex::escape(find);
        if is_word {
            format!("\\b{}\\b", escaped)
        } else {
            escaped
        }
    } else {
        if is_word {
            format!("\\b{}\\b", find)
        } else {
            find.clone()
        }
    };

    // Build regex (bytes)
    let regex_res = regex::bytes::RegexBuilder::new(&pattern_str)
        .case_insensitive(case_insensitive)
        .multi_line(multi_line)
        .dot_matches_new_line(dot_matches)
        .build();
    let re = match regex_res {
        Ok(r) => r,
        Err(e) => {
            eprintln!("error: invalid regex {}", e);
            std::process::exit(1);
        }
    };

    // Build replacement intermediate (if not fixed, unescape; else raw)
    let replacement_intermediate: Vec<u8> = if fixed_strings {
        replace_with.as_bytes().to_vec()
    } else {
        unescape_replacement(replace_with).into_bytes()
    };

    if files.is_empty() {
        // stdin -> stdout
        let mut input = Vec::new();
        match io::stdin().read_to_end(&mut input) {
            Ok(_) => {},
            Err(e) => {
                eprintln!("error: {}", e);
                std::process::exit(1);
            }
        }
        let output: Vec<u8> = if fixed_strings {
            if max_replacements == 0 {
                re.replace_all(&input[..], regex::bytes::NoExpand(&replacement_intermediate)).into_owned()
            } else {
                re.replacen(&input[..], max_replacements, regex::bytes::NoExpand(&replacement_intermediate)).into_owned()
            }
        } else {
            if max_replacements == 0 {
                re.replace_all(&input[..], &replacement_intermediate[..]).into_owned()
            } else {
                re.replacen(&input[..], max_replacements, &replacement_intermediate[..]).into_owned()
            }
        };
        // preview with stdin is same as normal (no headers)
        match io::stdout().write_all(&output) {
            Ok(_) => {},
            Err(e) => {
                if e.kind() == io::ErrorKind::BrokenPipe {
                    std::process::exit(0);
                } else {
                    eprintln!("error: {}", e);
                    std::process::exit(1);
                }
            }
        }
        // Ensure flush? Check for errors on flush as well (e.g., /dev/full may fail on flush, not write_all? Actually write_all to /dev/full fails immediately with ENOSPC, as we saw. Good. But to be safe, flush and handle.
        match io::stdout().flush() {
            Ok(_) => {},
            Err(e) => {
                if e.kind() == io::ErrorKind::BrokenPipe {
                    std::process::exit(0);
                } else {
                    eprintln!("error: {}", e);
                    std::process::exit(1);
                }
            }
        }
    } else {
        // files mode: pre-validate all for read errors (two-phase)
        // Phase 1: metadata for all, any failure => invalid path (first such in order)
        let mut metadatas: Vec<std::fs::Metadata> = Vec::with_capacity(files.len());
        for p in &files {
            match std::fs::metadata(p) {
                Ok(m) => metadatas.push(m),
                Err(_) => {
                    // Any metadata failure => invalid path (lossy)
                    eprintln!("error: invalid path: {}", p.to_string_lossy());
                    std::process::exit(1);
                }
            }
        }
        // Phase 2: check is_file and read all, first failure in order wins
        let mut contents: Vec<Vec<u8>> = Vec::with_capacity(files.len());
        for (idx, p) in files.iter().enumerate() {
            let meta = &metadatas[idx];
            if !meta.is_file() {
                // ENODEV
                let e = std::io::Error::from_raw_os_error(19);
                eprintln!("error: {}", e);
                std::process::exit(1);
            }
            match std::fs::read(p) {
                Ok(data) => contents.push(data),
                Err(e) => {
                    if e.kind() == io::ErrorKind::NotFound {
                        eprintln!("error: invalid path: {}", p.to_string_lossy());
                    } else {
                        eprintln!("error: {}", e);
                    }
                    std::process::exit(1);
                }
            }
        }

        if preview {
            // preview: output to stdout, no headers for single, headers for multi
            let mut out_buf: Vec<u8> = Vec::new();
            if files.len() == 1 {
                let new_content = apply_replacement(&re, &contents[0], &replacement_intermediate, fixed_strings, max_replacements);
                out_buf.extend_from_slice(&new_content);
            } else {
                for (idx, p) in files.iter().enumerate() {
                    let header = format!("----- FILE {} -----\n", p.to_string_lossy());
                    out_buf.extend_from_slice(header.as_bytes());
                    let new_content = apply_replacement(&re, &contents[idx], &replacement_intermediate, fixed_strings, max_replacements);
                    out_buf.extend_from_slice(&new_content);
                }
            }
            match io::stdout().write_all(&out_buf) {
                Ok(_) => {},
                Err(e) => {
                    if e.kind() == io::ErrorKind::BrokenPipe {
                        std::process::exit(0);
                    } else {
                        eprintln!("error: {}", e);
                        std::process::exit(1);
                    }
                }
            }
            match io::stdout().flush() {
                Ok(_) => {},
                Err(e) => {
                    if e.kind() == io::ErrorKind::BrokenPipe {
                        std::process::exit(0);
                    } else {
                        eprintln!("error: {}", e);
                        std::process::exit(1);
                    }
                }
            }
        } else {
            // normal: write each file via temp + rename, collecting write errors
            let mut failures: Vec<(PathBuf, String, String)> = Vec::new(); // (original path, io error display, temp path display)
            for (idx, p) in files.iter().enumerate() {
                let new_content = apply_replacement(&re, &contents[idx], &replacement_intermediate, fixed_strings, max_replacements);
                // Resolve real path for temp dir and rename target (canonicalize)
                // Canonicalize may fail? But pre-validation succeeded (metadata ok), so canonicalize should succeed (unless race). If fails, treat as invalid path? Actually for valid files, canonicalize should succeed. If fails, use original parent?
                let real_path: PathBuf = match std::fs::canonicalize(p) {
                    Ok(r) => r,
                    Err(e) => {
                        // If canonicalize fails, treat as write failure? Or invalid path? Unlikely. Report as Failed processing with original?
                        // For now, report as Failed processing with temp = original parent + dummy?
                        // Generate dummy temp path for message
                        let parent = p.parent().unwrap_or(Path::new("."));
                        // Try to make absolute for temp display? Use current_dir + parent?
                        // Simplify: use parent display + "/.tmpXXXXXX" dummy
                        let dummy_temp = format!("{}/.tmp{}", parent.to_string_lossy(), random_suffix());
                        failures.push((p.clone(), e.to_string(), dummy_temp));
                        continue;
                    }
                };
                let parent = real_path.parent().unwrap_or(Path::new("/")).to_path_buf();
                // Generate temp path: parent + "/.tmp" + 6 random alnum
                let temp_name = format!(".tmp{}", random_suffix());
                let temp_path = parent.join(&temp_name);
                let temp_display = temp_path.to_string_lossy().to_string();
                // Try to create temp file, write, chmod, rename
                // Use File::create (truncate if exists)
                let write_result: io::Result<()> = (|| {
                    // Create
                    let mut f = std::fs::File::create(&temp_path)?;
                    // Write
                    f.write_all(&new_content)?;
                    // Flush? Ensure data written
                    f.flush()?;
                    // Chmod to original mode (from metadatas[idx].permissions())
                    let perms = metadatas[idx].permissions();
                    std::fs::set_permissions(&temp_path, perms)?;
                    drop(f);
                    // Rename onto real_path
                    std::fs::rename(&temp_path, &real_path)?;
                    Ok(())
                })();
                match write_result {
                    Ok(_) => {},
                    Err(e) => {
                        // Clean up temp if exists (ignore errors)
                        let _ = std::fs::remove_file(&temp_path);
                        failures.push((p.clone(), e.to_string(), temp_display));
                        continue;
                    }
                }
            }
            if !failures.is_empty() {
                eprintln!("error: Failed processing some inputs");
                for (orig, err_display, temp_display) in failures {
                    eprintln!("    {}: {} at path \"{}\"", orig.to_string_lossy(), err_display, temp_display);
                }
                eprintln!();
                std::process::exit(1);
            }
        }
    }
}

fn parse_flags(flags: &str) -> (bool, bool, bool, bool) {
    // returns (case_insensitive, multi_line, dot_matches, is_word)
    // case_insensitive, dot_matches are sequential (w acts as false)
    // is_word is contains w
    // multi_line is contains-based with priority
    let mut case_insensitive = false;
    let mut dot_matches = false;
    for c in flags.chars() {
        match c {
            'c' => case_insensitive = false,
            'i' => case_insensitive = true,
            'w' => {
                case_insensitive = false;
                dot_matches = false;
            }
            's' => {
                dot_matches = true;
            }
            _ => {}
        }
    }
    // Note: 'm'/'e' don't affect case/dot, only multiline via contains rule
    // But need to handle 's'/'w' sequential correctly when interleaved with other chars? Already done (only s/w matter for dot, c/i/w for case)
    // For dot, need to consider last among s/w only (other chars ignored) - our loop does that (only s/w change dot)
    // For case, last among c/i/w - our loop does that
    let is_word = flags.contains('w');
    let multi_line = if flags.contains('e') || flags.contains('w') {
        false
    } else if flags.contains('m') {
        true
    } else if flags.contains('s') {
        false
    } else {
        true
    };
    (case_insensitive, multi_line, dot_matches, is_word)
}

fn validate_replacement(repl: &str) -> Result<(), String> {
    // Scan raw replacement for ambiguous $<digits><ascii alnum/_>
    // Handling: $$ (skip 2), ${...} (skip to } if found), $+digits (check trailing), $+letter/_ (skip longest), else literal
    let bytes = repl.as_bytes();
    let len = bytes.len();
    let mut i = 0;
    while i < len {
        if bytes[i] != b'$' {
            // Advance by one char (handle multi-byte UTF-8 correctly for indexing? Since repl is &str (UTF-8), bytes[i] is byte, not char.
            // For '$' check, '$' is ASCII (single byte), so bytes[i]==b'$' is correct for char '$'.
            // For non-'$', advance by char len (to skip multi-byte correctly for next '$' search? Actually we just need to find next '$', so advance by 1 byte is fine? No, for multi-byte chars, advancing by 1 byte could land inside multi-byte sequence, but since we only check for '$' (ASCII, single byte, never part of multi-byte), advancing by 1 byte is safe? Multi-byte UTF-8 bytes are all >=0x80, never 0x24 ('$'), so safe to advance by 1 byte when not '$'. Good.
            // However, for correct char counting for carets (which count per char, not byte), we need char indices later. For now, just scan bytes.
            i += 1;
            // But need to handle UTF-8 char boundaries for i increment? Advancing by 1 byte when at multi-byte start will land inside char, but next iteration will see byte >=0x80 (not '$'), advance again, eventually past char. Good. So byte-wise scan works for finding '$'.
            continue;
        }
        // Found '$' at i
        if i + 1 >= len {
            // '$' at end, literal, done
            break;
        }
        let next = bytes[i+1];
        if next == b'$' {
            // Escaped $$, skip 2
            i += 2;
            continue;
        } else if next == b'{' {
            // Braced: find closing '}'
            // Find first '}' after i+2
            if let Some(rel) = repl[i+2..].find('}') {
                // Skip past '}': i+2+rel+1
                i = i + 2 + rel + 1;
                continue;
            } else {
                // No closing, literal "$" + "{"? Treat '$' as literal, advance 1
                i += 1;
                continue;
            }
        } else if next.is_ascii_digit() {
            // Numbered: parse longest digits
            let mut j = i + 1;
            while j < len && bytes[j].is_ascii_digit() {
                j += 1;
            }
            // Digits are bytes[i+1..j]
            // Check next char after digits (at j): if exists and is ascii alnum or '_' => ambiguous
            if j < len && (bytes[j].is_ascii_alphanumeric() || bytes[j] == b'_') {
                // Found ambiguous: digits = repl[i+1..j], trailing = longest alnum/_ starting at j
                let mut k = j;
                while k < len && (bytes[k].is_ascii_alphanumeric() || bytes[k] == b'_') {
                    k += 1;
                }
                // trailing is bytes[j..k]
                let digits_str = &repl[i+1..j]; // ASCII digits, safe slice (byte indices at char boundaries? Since digits are ASCII single-byte, and i is at '$' (ASCII), j is at byte after digits (could be inside multi-byte? No, since we stopped at non-digit, which could be start of multi-byte (>=0x80) or ASCII alnum? Actually if bytes[j] is >=0x80 (multi-byte start), then is_ascii_alphanumeric is false, so we wouldn't be in this branch (since we checked is_ascii...). Good. So j is at ASCII alnum/_ (single byte), safe. Similarly k advances only over ASCII alnum/_ (single-byte), so safe. Good. So slices are at char boundaries (ASCII). Good.
                let trailing_str = &repl[j..k];
                // Construct error message
                // First line: error: The numbered capture group `$<digits>` in the replacement text is ambiguous.
                // Second: hint: Use curly braces to disambiguate it `${<digits>}<trailing>`.
                // Third: snippet (raw repl with \t,\n,\r mapped to symbols)
                // Fourth: carets (spaces for chars before '$', '^' for digits+trailing chars)
                // Need to handle snippet mapping and carets per char (not byte) for Unicode?
                // For carets, need to count chars (Unicode scalars) before '$' in mapped snippet? Since mapping changes \t (1 char) to \u{2409} (1 char), char count same. Good. So count chars in raw up to i for spaces.
                // For digits+trailing, all ASCII (single-byte), so char count == byte len (j-i-1 + k-j = k-i-1). Actually digits len = j-(i+1), trailing len = k-j, total = k-i-1. Carets = total (since '$' replaced with space, digits+trailing with '^'? Wait earlier we deduced carets cover digits+trailing (without '$'), and '$' itself is space. For "$1a" (i=0, digits "1" (1 char), trailing "a" (1 char), total digits+trailing = 2 chars "1a", carets 2. Spaces for before '$' (0 chars) + '$' itself (1 space) = 1 space? Actually carets line for "$1a" alone is " ^^" (space + 2 carets, len 3). That's 1 space (for '$') + 2 carets (for "1a"). Good. For "A$1aB" (prefix 'A' (1 char) + '$' (1) = 2 spaces, carets for "1aB" (3 chars: '1','a','B')). Good. So spaces = chars_before_$ + 1 (for '$' itself), carets = digits_len + trailing_len.
                // Need to count chars_before_$ as number of Unicode scalars in repl[..i] (raw) after mapping? Since mapping preserves char count (each \t->1 char, etc.), same. Good. So count chars in repl[..i].
                let chars_before = repl[..i].chars().count();
                let spaces = chars_before + 1; // +1 for '$' itself
                let carets_len = (j - (i+1)) + (k - j); // all ASCII, byte len == char len
                // Snippet mapped: replace \t,\n,\r with symbols
                let snippet_mapped: String = repl.chars().map(|c| {
                    match c {
                        '\t' => '\u{2409}',
                        '\n' => '\u{240A}',
                        '\r' => '\u{240D}',
                        _ => c,
                    }
                }).collect();
                // Construct message
                let mut msg = String::new();
                msg.push_str(&format!("error: The numbered capture group `${}` in the replacement text is ambiguous.\n", &repl[i..j])); // repl[i..j] is "$<digits>" (e.g., "$1", "$12")
                msg.push_str(&format!("hint: Use curly braces to disambiguate it `${{{}}}{}`.\n", digits_str, trailing_str));
                msg.push_str(&format!("{}\n", snippet_mapped));
                // Carets line: spaces + '^'*carets_len + '\n'
                // Note: spaces are ASCII spaces (single byte), carets are '^' (single byte). Good.
                for _ in 0..spaces {
                    msg.push(' ');
                }
                for _ in 0..carets_len {
                    msg.push('^');
                }
                msg.push('\n');
                return Err(msg);
            } else {
                // No trailing alnum, not ambiguous, skip past digits
                i = j;
                continue;
            }
        } else if next.is_ascii_alphabetic() || next == b'_' {
            // Named: parse longest alnum/_ (ASCII only? What about Unicode after $? Since next is ASCII letter/_, parse only ASCII alnum/_? Unicode breaks? As observed, $aé (where é is Unicode) parses only "a" (1 char), é separate. Good. So parse only ASCII alnum/_.
            let mut j = i + 1;
            while j < len && (bytes[j].is_ascii_alphanumeric() || bytes[j] == b'_') {
                j += 1;
            }
            i = j;
            continue;
        } else {
            // '$' + other (non-alnum, not {, not $, e.g., '-', ' ', '\', end, Unicode, etc.): literal '$', advance 1
            i += 1;
            continue;
        }
    }
    Ok(())
}

fn unescape_replacement(raw: &str) -> String {
    // Two-pass unescaping with Bug 1 (skip after valid \x/\u)
    // Iterate over chars with index handling for \x/\u (which are ASCII, so byte indices safe? But need to handle multi-byte trailing skip per char)
    // Simplest: collect chars into Vec<char>, iterate with index over chars (not bytes), handling \x/\u by looking ahead chars (which should be ASCII hex? Hex digits are ASCII, so char == byte for those. Good.)
    let chars: Vec<char> = raw.chars().collect();
    let len = chars.len();
    let mut out = String::new();
    let mut i = 0;
    while i < len {
        if chars[i] != '\\' {
            out.push(chars[i]);
            i += 1;
            continue;
        }
        // Found '\\' at i
        if i + 1 >= len {
            // Trailing '\' at end, literal
            out.push('\\');
            i += 1;
            continue;
        }
        let nxt = chars[i+1];
        match nxt {
            'n' => { out.push('\n'); i += 2; },
            't' => { out.push('\t'); i += 2; },
            'r' => { out.push('\r'); i += 2; },
            '\\' => { out.push('\\'); i += 2; },
            '\'' => { out.push('\''); i += 2; },
            '"' => { out.push('"'); i += 2; },
            'x' => {
                // Need 2 hex after x (i+2, i+3)
                if i + 3 < len && chars[i+2].is_ascii_hexdigit() && chars[i+3].is_ascii_hexdigit() {
                    // Valid \xHH
                    let hex_str: String = vec![chars[i+2], chars[i+3]].into_iter().collect();
                    let val = u8::from_str_radix(&hex_str, 16).unwrap(); // 0-255, always valid
                    // Convert to char via from_u32 (0-255 always valid, including 0x00? char::from_u32(0) is Some('\0'), valid. Good.
                    let ch = char::from_u32(val as u32).unwrap();
                    out.push(ch);
                    i += 4; // past \xHH
                    // Bug 1: skip next single char (if any)
                    if i < len {
                        i += 1; // skip (discard)
                    }
                } else {
                    // Invalid, literal '\', advance 1 (leave 'x' for next)
                    out.push('\\');
                    i += 1;
                }
            },
            'u' => {
                // Need 4 hex after u (i+2..i+5)
                if i + 5 < len && chars[i+2].is_ascii_hexdigit() && chars[i+3].is_ascii_hexdigit() && chars[i+4].is_ascii_hexdigit() && chars[i+5].is_ascii_hexdigit() {
                    let hex_str: String = vec![chars[i+2], chars[i+3], chars[i+4], chars[i+5]].into_iter().collect();
                    let val = u32::from_str_radix(&hex_str, 16).unwrap(); // 0-FFFF
                    match char::from_u32(val) {
                        Some(ch) => {
                            out.push(ch);
                            i += 6; // past \uHHHH
                            // Bug 1: skip next
                            if i < len {
                                i += 1;
                            }
                        },
                        None => {
                            // Surrogate (D800-DFFF), invalid, literal '\', advance 1
                            out.push('\\');
                            i += 1;
                        }
                    }
                } else {
                    // Invalid, literal
                    out.push('\\');
                    i += 1;
                }
            },
            _ => {
                // Invalid escape (including 'U', 'a', 'b', 'f', 'v', 'c', 'd', 's', 'w', '/', '0', etc.): literal '\', advance 1
                out.push('\\');
                i += 1;
            }
        }
    }
    out
}

fn apply_replacement(re: &regex::bytes::Regex, input: &[u8], replacement: &[u8], fixed: bool, limit: usize) -> Vec<u8> {
    if fixed {
        if limit == 0 {
            re.replace_all(input, regex::bytes::NoExpand(replacement)).into_owned()
        } else {
            re.replacen(input, limit, regex::bytes::NoExpand(replacement)).into_owned()
        }
    } else {
        if limit == 0 {
            re.replace_all(input, &replacement[..]).into_owned()
        } else {
            re.replacen(input, limit, &replacement[..]).into_owned()
        }
    }
}

fn random_suffix() -> String {
    // Generate 6 random alphanumeric (A-Za-z0-9) using fastrand? Use std + time + pid for seed? Simpler: use tempfile's fastrand? Actually fastrand crate is available via tempfile dependency? But we can just use std::collections::hash_map::RandomState? Or use /dev/urandom?
    // Simplest: read 6 bytes from /dev/urandom (or use getrandom? No, use std::fs::read /dev/urandom? On Linux, /dev/urandom always exists. Good.
    // Fallback to time+pid based pseudo-random if /dev/urandom fails.
    const ALPHANUM: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    let mut bytes = [0u8; 6];
    // Try /dev/urandom
    if let Ok(mut f) = std::fs::File::open("/dev/urandom") {
        use std::io::Read;
        if f.read_exact(&mut bytes).is_ok() {
            let mut s = String::with_capacity(6);
            for b in bytes {
                s.push(ALPHANUM[(b as usize) % 62] as char);
            }
            return s;
        }
    }
    // Fallback: use time + pid + counter
    use std::time::{SystemTime, UNIX_EPOCH};
    let now = SystemTime::now().duration_since(UNIX_EPOCH).map(|d| d.as_nanos()).unwrap_or(0);
    let pid = std::process::id() as u128;
    // Simple LCG? Use fastrand-like? Just use hash of now+pid+counter
    static COUNTER: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
    let cnt = COUNTER.fetch_add(1, std::sync::atomic::Ordering::Relaxed) as u128;
    let mut seed = now ^ (pid << 32) ^ (cnt << 64);
    // LCG parameters from Numerical Recipes?
    let mut s = String::with_capacity(6);
